function viewFromPath(pathname:string){
  const match=pathname.match(/^\/mo-hinh-([1-6])\/?$/);
  return match?`model-${match[1]}`:"home";
}

function pathFromView(view:string){
  const match=view.match(/^model-([1-6])$/);
  return match?`/mo-hinh-${match[1]}`:"/";
}

