const defaultGuide:GuideStep[]=steps.map(s=>addDefaultPreparation({id:s.id,n:s.n,title:s.title,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages||s.details.map(()=>[]),calloutImages:s.calloutImages||[],defaultVideo:fixedVideos[s.id]}));
function upgradeGuide(saved:GuideStep[]){
  const firstImage=saved.find(s=>s.id==="buoc-chuan-bi")?.detailImages?.flat()?.[0];
  const menuBeforeDashboard=saved.findIndex(s=>s.id==="buoc-8")<saved.findIndex(s=>s.id==="buoc-9")&&saved.find(s=>s.id==="buoc-8")?.title.includes("menu");
  const hasPaymentGuide=saved.find(s=>s.id==="buoc-2")?.detailImages?.flat()?.includes("m1-payment-01.png");
  const hasCuratedImages=saved.find(s=>s.id==="buoc-8")?.detailImages?.flat()?.includes("m1-extra-s08-02.jpg");
  const noBlankOpeningImage=firstImage==="m1-s00-01.jpg";
  if(!noBlankOpeningImage||!menuBeforeDashboard||!hasPaymentGuide||!hasCuratedImages)return defaultGuide;
  return saved.map((s,i)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0"),defaultVideo:fixedVideos[s.id]}));
}

function CodeCard({file}:{file:typeof codeFiles[number]}){const[code,setCode]=useState("Đang tải mã…"),[copied,setCopied]=useState(false);useEffect(()=>{fetch(file.path).then(r=>r.text()).then(setCode).catch(()=>setCode("Không thể tải mã."))},[file.path]);async function copy(){await navigator.clipboard.writeText(code);setCopied(true);setTimeout(()=>setCopied(false),1600)}return <article className="code-card"><div className="code-head"><div><span>{file.n}</span><h3>{file.title}</h3><p>{file.where}</p></div><div><button onClick={copy}>{copied?"✓ Đã sao chép":"Sao chép mã"}</button><a href={file.path} download={file.download}>Tải tệp</a></div></div><pre><code>{code}</code></pre></article>}

function SeekableVideo({src,label}:{src:string;label:string}){
  const videoRef=useRef<HTMLVideoElement>(null);
  function seek(seconds:number){
    const video=videoRef.current;
    if(!video)return;
    const next=Math.max(0,video.currentTime+seconds);
    video.currentTime=Number.isFinite(video.duration)?Math.min(video.duration,next):next;
  }
  return <div className="seekable-video"><video ref={videoRef} controls playsInline preload="metadata" src={src} aria-label={label}/><div className="video-seek-controls" aria-label="Điều khiển tua video"><button type="button" onClick={()=>seek(-10)}>↶ Lùi 10 giây</button><span>Kéo thanh thời gian trên video để tua tới đoạn bạn muốn xem.</span><button type="button" onClick={()=>seek(10)}>Tiến 10 giây ↷</button></div></div>
}

function VideoBox({stepId,isAdmin,defaultVideo}:{stepId:string;isAdmin:boolean;defaultVideo?:string}){const[url,setUrl]=useState<string|null>(defaultVideo||null),[uploading,setUploading]=useState(false),[deleting,setDeleting]=useState(false),[notice,setNotice]=useState("");useEffect(()=>{fetch(`/api/videos/${stepId}?meta=1`).then(r=>r.json()).then(d=>setUrl(d.hasVideo?d.url:null)).catch(()=>{})},[stepId]);async function upload(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;setUploading(true);setNotice("");try{await uploadToBlob(`guide-videos/${stepId}`,file,{access:"private",handleUploadUrl:"/api/blob-upload",multipart:file.size>20*1024*1024,contentType:file.type});setUrl(`/api/videos/${stepId}?v=${Date.now()}`);setNotice("Đã cập nhật video.")}catch(error){setNotice(error instanceof Error?error.message:"Không thể tải video.")}finally{setUploading(false);e.target.value=""}}async function remove(){if(!url||!confirm("Bạn có chắc muốn xóa video khỏi bước này không?"))return;setDeleting(true);setNotice("");try{const r=await fetch(`/api/videos/${stepId}`,{method:"DELETE"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Không thể xóa video.");setUrl(null);setNotice("Đã xóa video.")}catch(error){setNotice(error instanceof Error?error.message:"Không thể xóa video.")}finally{setDeleting(false)}}return <div className="step-video"><div className="video-label"><b>Video thao tác của bước này</b><span>{url?"Có thể kéo thanh thời gian, lùi hoặc tiến 10 giây":"Có thể tải video lên sau"}</span></div>{url?<SeekableVideo src={url} label="Video thao tác của bước này"/>:<div className="video-empty"><b>Chưa có video</b><span>Video của bước này sẽ hiển thị tại đây.</span></div>}{isAdmin&&!defaultVideo&&<div className="video-admin-actions"><label className="replace-video">{uploading?"Đang tải…":url?"↻ Thay video":"＋ Tải video lên"}<input type="file" accept="video/mp4,video/webm,video/quicktime" disabled={uploading||deleting} onChange={upload}/></label>{url&&<button className="delete-video" onClick={remove} disabled={deleting||uploading}>{deleting?"Đang xóa…":"Xóa video"}</button>}</div>}{notice&&<div className="upload-notice">{notice}</div>}</div>}

type RedBox={x:number;y:number;width:number;height:number};

function ImageAnnotator({imageName,imageSrc,onClose,onSaved}:{imageName:string;imageSrc:string;onClose:()=>void;onSaved:()=>void}){
  const canvasRef=useRef<HTMLCanvasElement>(null),imageRef=useRef<HTMLImageElement|null>(null);
  const[boxes,setBoxes]=useState<RedBox[]>([]),[draft,setDraft]=useState<RedBox|null>(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState("");
  function draw(boxList=boxes,current=draft){const canvas=canvasRef.current,img=imageRef.current;if(!canvas||!img)return;const ctx=canvas.getContext("2d");if(!ctx)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);ctx.strokeStyle="#e00000";ctx.lineWidth=Math.max(5,Math.round(canvas.width/320));ctx.lineJoin="round";[...boxList,...(current?[current]:[])].forEach(box=>ctx.strokeRect(box.x,box.y,box.width,box.height))}
  useEffect(()=>{const img=new Image();img.crossOrigin="anonymous";img.onload=()=>{imageRef.current=img;const canvas=canvasRef.current;if(!canvas)return;canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;setLoading(false);requestAnimationFrame(()=>draw([],null))};img.onerror=()=>{setError("Không thể mở ảnh này để chỉnh sửa.");setLoading(false)};img.src=imageSrc;return()=>{img.onload=null;img.onerror=null}},[imageSrc]);
  useEffect(()=>{if(!loading)draw()},[boxes,draft,loading]);
  function point(e:ReactPointerEvent<HTMLCanvasElement>){const canvas=e.currentTarget,rect=canvas.getBoundingClientRect();return{x:(e.clientX-rect.left)*canvas.width/rect.width,y:(e.clientY-rect.top)*canvas.height/rect.height}}
  function start(e:ReactPointerEvent<HTMLCanvasElement>){if(loading||saving)return;e.currentTarget.setPointerCapture(e.pointerId);const p=point(e);setDraft({x:p.x,y:p.y,width:0,height:0})}
  function move(e:ReactPointerEvent<HTMLCanvasElement>){if(!draft)return;const p=point(e);setDraft({...draft,width:p.x-draft.x,height:p.y-draft.y})}
  function finish(e:ReactPointerEvent<HTMLCanvasElement>){if(!draft)return;e.currentTarget.releasePointerCapture(e.pointerId);if(Math.abs(draft.width)>8&&Math.abs(draft.height)>8)setBoxes(current=>[...current,draft]);setDraft(null)}
  async function save(){const canvas=canvasRef.current;if(!canvas||!boxes.length)return;setSaving(true);setError("");try{draw(boxes,null);const preferred=/\.jpe?g$/i.test(imageName)?"image/jpeg":"image/png";const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,preferred,preferred==="image/jpeg"?0.94:undefined));if(!blob)throw new Error("Không thể tạo ảnh sau khi khoanh.");if(blob.size>8*1024*1024)throw new Error("Ảnh sau khi khoanh lớn hơn 8 MB. Hãy dùng ảnh có kích thước nhỏ hơn.");await uploadToBlob(`guide-images/${imageName}`,blob,{access:"private",handleUploadUrl:"/api/blob-upload",contentType:preferred});onSaved();onClose()}catch(reason){setError(reason instanceof Error?reason.message:"Không thể lưu ảnh.")}finally{setSaving(false)}}
  return <div className="annotator-backdrop" role="dialog" aria-modal="true" aria-label="Khoanh đỏ trên ảnh"><div className="annotator-panel"><div className="annotator-head"><div><b>Khoanh đỏ trên ảnh</b><span>Kéo chuột hoặc ngón tay để tạo khung chữ nhật màu đỏ.</span></div><button type="button" onClick={onClose} aria-label="Đóng">×</button></div><div className="annotator-stage">{loading&&<div className="annotator-loading">Đang mở ảnh…</div>}<canvas ref={canvasRef} className={loading?"is-loading":""} onPointerDown={start} onPointerMove={move} onPointerUp={finish} onPointerCancel={()=>setDraft(null)}/></div>{error&&<div className="annotator-error">{error}</div>}<div className="annotator-footer"><button type="button" className="secondary" onClick={()=>setBoxes(current=>current.slice(0,-1))} disabled={!boxes.length||saving}>↶ Hoàn tác</button><span>{boxes.length?`Đã tạo ${boxes.length} khung đỏ.`:"Hãy kéo trực tiếp trên ảnh để khoanh vùng cần chú ý."}</span><div><button type="button" className="secondary" onClick={onClose} disabled={saving}>Hủy</button><button type="button" className="save-annotation" onClick={save} disabled={!boxes.length||saving}>{saving?"Đang lưu…":"Lưu ảnh"}</button></div></div></div></div>
}

function StepCard({step,index,total,isAdmin,onChange,onMove,onDelete}:{step:GuideStep;index:number;total:number;isAdmin:boolean;onChange:(step:GuideStep)=>void;onMove:(direction:-1|1)=>void;onDelete:()=>void}){
  const[done,setDone]=useState(false),[photo,setPhoto]=useState<string|null>(null),[annotationTarget,setAnnotationTarget]=useState<string|null>(null),[versions,setVersions]=useState<Record<string,number>>({}),[uploading,setUploading]=useState<string|null>(null),[notice,setNotice]=useState("");
  useEffect(()=>setDone(localStorage.getItem(`done-${step.id}`)==="1"),[step.id]);
  function toggle(){const next=!done;setDone(next);localStorage.setItem(`done-${step.id}`,next?"1":"0")}
  const imageUrl=(name:string)=>`/api/images/${encodeURIComponent(name)}?v=${versions[name]||0}`;
  async function uploadImage(group:"detail"|"callout",detailIndex:number,imageIndex:number|null,e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;const ext=(file.name.split(".").pop()||"jpg").replace(/[^a-z0-9]/gi,"").toLowerCase();const name=imageIndex===null?`custom-${step.id}-${Date.now()}.${ext}`:(group==="callout"?step.calloutImages[imageIndex]:step.detailImages[detailIndex][imageIndex]);setUploading(name);setNotice("");try{await uploadToBlob(`guide-images/${name}`,file,{access:"private",handleUploadUrl:"/api/blob-upload",contentType:file.type});if(imageIndex===null){if(group==="callout")onChange({...step,calloutImages:[...step.calloutImages,name]});else{const groups=step.detailImages.map(g=>[...g]);groups[detailIndex]=[...(groups[detailIndex]||[]),name];onChange({...step,detailImages:groups})}}setVersions(v=>({...v,[name]:Date.now()}));setNotice("Đã cập nhật ảnh. Bấm “Lưu và cập nhật” để khách hàng nhìn thấy bố cục mới.")}catch(error){setNotice(error instanceof Error?error.message:"Không thể tải ảnh.")}finally{setUploading(null);e.target.value=""}}
  function removeImage(group:"detail"|"callout",detailIndex:number,imageIndex:number){if(group==="callout")onChange({...step,calloutImages:step.calloutImages.filter((_,i)=>i!==imageIndex)});else{const groups=step.detailImages.map(g=>[...g]);groups[detailIndex]=(groups[detailIndex]||[]).filter((_,i)=>i!==imageIndex);onChange({...step,detailImages:groups})}}
  function images(group:"detail"|"callout",detailIndex:number,list:string[],label:string){return <div className="paired-images">{list.map((img,i)=><div className="image-card" key={img}><button className="image-open" onClick={()=>setPhoto(imageUrl(img))}><img src={imageUrl(img)} alt={`${label} – hình ${i+1}`} loading={index<2?"eager":"lazy"}/><span>Hình minh họa {i+1} · Bấm để xem lớn</span></button>{isAdmin&&<div className="image-admin-actions"><button className="annotate-image" onClick={()=>setAnnotationTarget(img)}>▣ Khoanh đỏ</button><label className="replace-image">{uploading===img?"Đang tải…":"↻ Thay ảnh"}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" disabled={uploading===img} onChange={e=>uploadImage(group,detailIndex,i,e)}/></label><button onClick={()=>removeImage(group,detailIndex,i)}>Bỏ ảnh</button></div>}</div>)}{isAdmin&&<label className="add-image">＋ Thêm ảnh cho nội dung này<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>uploadImage(group,detailIndex,null,e)}/></label>}</div>}
  function updateDetail(i:number,value:string){const details=[...step.details];details[i]=value;onChange({...step,details})}
  function addDetail(){onChange({...step,details:[...step.details,"Nhập nội dung thao tác mới"],detailImages:[...step.detailImages,[]]})}
  function deleteDetail(i:number){if(!confirm("Xóa ý hướng dẫn này?"))return;onChange({...step,details:step.details.filter((_,x)=>x!==i),detailImages:step.detailImages.filter((_,x)=>x!==i)})}
  function updatePreparation(kind:keyof StepPreparation,value:string){
    const current=step.preparation||{manual:[],automatic:[]};
    onChange({...step,preparation:{...current,[kind]:value.split("\n").map(line=>line.trim()).filter(Boolean)}});
  }
  const hasPreparation=Boolean(step.preparation&&(step.preparation.manual.length||step.preparation.automatic.length));
  return <><article className={`step paired-step ${done?"done":""}`} id={step.id}><div className="step-head"><div className="number">{String(index+1).padStart(2,"0")}</div><div><span>BƯỚC {index+1} / {total}</span>{isAdmin?<input className="admin-title-input" value={step.title} onChange={e=>onChange({...step,title:e.target.value})}/>:<h2>{step.title}</h2>}</div>{isAdmin?<div className="step-admin-actions"><button onClick={()=>onMove(-1)} disabled={index===0}>↑ Lên</button><button onClick={()=>onMove(1)} disabled={index===total-1}>↓ Xuống</button><button className="danger" onClick={onDelete}>Xóa bước</button></div>:<button onClick={toggle}>{done?"✓ Đã hoàn thành":"Đánh dấu hoàn thành"}</button>}</div>{(hasPreparation||isAdmin)&&(step.preparation?<div className={`step-preparation ${isAdmin?"is-editing":""}`}><section className="prepare-manual"><div className="prepare-label"><span>✓</span><b>BẠN CẦN CHUẨN BỊ TRƯỚC</b></div>{isAdmin?<textarea aria-label="Nội dung cần chuẩn bị trước" value={step.preparation.manual.join("\n")} placeholder="Mỗi ý trên một dòng" onChange={e=>updatePreparation("manual",e.target.value)}/>:<ul>{step.preparation.manual.map((item,i)=><li key={i}>{item}</li>)}</ul>}</section><section className="prepare-automatic"><div className="prepare-label"><span>↻</span><b>HỆ THỐNG TỰ ĐỘNG THỰC HIỆN</b></div>{isAdmin?<textarea aria-label="Nội dung hệ thống tự động" value={step.preparation.automatic.join("\n")} placeholder="Mỗi ý trên một dòng" onChange={e=>updatePreparation("automatic",e.target.value)}/>:<ul>{step.preparation.automatic.map((item,i)=><li key={i}>{item}</li>)}</ul>}</section>{isAdmin&&<button className="remove-preparation" onClick={()=>onChange({...step,preparation:undefined})}>Xóa khung chuẩn bị</button>}</div>:<button className="add-preparation" onClick={()=>onChange({...step,preparation:{manual:["Nhập việc người dùng cần chuẩn bị"],automatic:["Nhập phần hệ thống tự động thực hiện"]}})}>＋ Thêm ghi chú chuẩn bị</button>)}{notice&&<div className="upload-notice paired-notice">{notice}</div>}<div className="paired-flow">{step.callout&&<section className="paired-unit callout-unit"><div className="book-callout">{isAdmin?<><input value={step.callout.title} onChange={e=>onChange({...step,callout:{...step.callout!,title:e.target.value}})}/><textarea value={step.callout.text} onChange={e=>onChange({...step,callout:{...step.callout!,text:e.target.value}})}/><button className="inline-delete" onClick={()=>onChange({...step,callout:undefined,calloutImages:[]})}>Xóa khung lưu ý</button></>:<><b>{step.callout.title}</b><p>{step.callout.text}</p></>}</div>{images("callout",-1,step.calloutImages,step.callout.title)}</section>}{isAdmin&&!step.callout&&<button className="add-callout" onClick={()=>onChange({...step,callout:{title:"Tiêu đề lưu ý",text:"Nhập nội dung lưu ý"}})}>＋ Thêm khung lưu ý</button>}{step.details.map((text,i)=><section className="paired-unit" key={i}><div className="book-action"><span>{i+1}</span>{isAdmin?<div className="admin-detail"><textarea value={text} onChange={e=>updateDetail(i,e.target.value)}/><button onClick={()=>deleteDetail(i)}>Xóa ý này</button></div>:<p>{text}</p>}</div>{images("detail",i,step.detailImages[i]||[],`Thao tác ${i+1}`)}</section>)}{isAdmin&&<button className="add-detail" onClick={addDetail}>＋ Thêm ý hướng dẫn vào bước này</button>}</div><VideoBox stepId={step.id} isAdmin={isAdmin} defaultVideo={step.defaultVideo}/></article>{photo&&<div className="lightbox" onClick={()=>setPhoto(null)}><button>×</button><img src={photo} alt={step.title}/></div>}{annotationTarget&&<ImageAnnotator imageName={annotationTarget} imageSrc={imageUrl(annotationTarget)} onClose={()=>setAnnotationTarget(null)} onSaved={()=>{setVersions(v=>({...v,[annotationTarget]:Date.now()}));setNotice("Đã lưu ảnh có khung đỏ. Khách hàng đang xem ảnh mới nhất.")}}/>}</>;
}

function ModelGuidePage({modelNumber,prompt,docPath,files=[],fullVideo,guide,savedGuide,isAdmin,saving,saveNotice,onSetGuide,onSave}:{modelNumber:1|2|3|4|5|6;prompt?:string;docPath?:string;files?:typeof codeFiles;fullVideo:string;guide:GuideStep[];savedGuide:GuideStep[];isAdmin:boolean;saving:boolean;saveNotice:string;onSetGuide:(value:GuideStep[]|((current:GuideStep[])=>GuideStep[]))=>void;onSave:()=>void}){
  const dirty=JSON.stringify(guide)!==JSON.stringify(savedGuide);
  const hasAssets=Boolean(prompt&&docPath&&files.length);
  const modelDescription=modelNumber===1?"Hệ thống tư vấn dinh dưỡng 28 ngày.":modelNumber===2?"Hệ thống dịch vụ 12 video ngắn mỗi tháng từ bộ ảnh khách cung cấp.":modelNumber===3?"Hệ thống biến kinh nghiệm và thương hiệu cá nhân thành sản phẩm tri thức có thể bán nhiều lần.":modelNumber===4?"Hệ thống báo cáo bán hàng tuần: mã tự tính số liệu, AI viết dự thảo và người quản lý duyệt trước khi gửi.":modelNumber===5?"Hệ thống vận hành thương mại điện tử một người: kiểm chứng nhu cầu, làm sản phẩm, phối hợp đối tác, xử lý đơn, tồn kho, hỗ trợ và đối soát.":"Hệ thống giới thiệu sản phẩm và nhận hoa hồng: kiểm chứng danh mục, phân loại nhu cầu, tạo thư nháp có kiểm duyệt, đối soát tiền và cảnh báo rủi ro.";
  function changeStep(i:number,next:GuideStep){onSetGuide(g=>g.map((s,x)=>x===i?next:s))}
  function moveStep(i:number,d:-1|1){onSetGuide(g=>{const next=[...g],to=i+d;if(to<0||to>=next.length)return g;[next[i],next[to]]=[next[to],next[i]];return next})}
  function deleteStep(i:number){if(confirm("Bạn có chắc muốn xóa toàn bộ bước này khỏi bản hướng dẫn?"))onSetGuide(g=>g.filter((_,x)=>x!==i))}
  function addStep(){const id=`m${modelNumber}-buoc-moi-${Date.now()}`;onSetGuide(g=>[...g,{id,n:String(g.length+1).padStart(2,"0"),title:"Bước hướng dẫn mới",details:["Nhập nội dung thao tác"],detailImages:[[]],calloutImages:[]}]);setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:"smooth"}),100)}
  const fileCountText=files.length===2?"Hai tệp mã":files.length===3?"Ba tệp mã":`${files.length} tệp mã`;
  return <>{isAdmin&&<div className="admin-savebar"><div><b>Chế độ quản trị nội dung · Mô hình {modelNumber}</b><span>{dirty?"Có thay đổi chưa lưu":"Mọi thay đổi đã được lưu"}</span></div><div><button className="discard" disabled={!dirty||saving} onClick={()=>onSetGuide(savedGuide)}>Hoàn tác thay đổi</button><button disabled={!dirty||saving} onClick={onSave}>{saving?"Đang lưu…":"Lưu và cập nhật cho khách hàng"}</button></div>{saveNotice&&<small>{saveNotice}</small>}</div>}<div className="model-subnav">{hasAssets&&<><a href={`#prompt-${modelNumber}`}>Câu lệnh</a><a href={`#codes-${modelNumber}`}>Bộ mã</a></>}<a href={`#steps-${modelNumber}`}>Thao tác</a><a href={`#full-video-${modelNumber}`}>Video A–Z</a></div><section className="hero" id={`top-${modelNumber}`}><div><span>MÔ HÌNH {modelNumber} · BỘ HƯỚNG DẪN ĐẦY ĐỦ</span><h1>{hasAssets?<>Từ câu lệnh và mã<br/><b>đến từng thao tác thực hiện</b></>:<>Biến tri thức thành sản phẩm<br/><b>bán được nhiều lần</b></>}</h1><p>{modelDescription} {hasAssets?`Câu lệnh, ${files.length===2?"hai":"ba"} tệp mã, ảnh và video được đặt trên cùng một trang.`:"Hướng dẫn được biên tập theo sách, sắp xếp theo diễn biến video và ghép với ảnh chụp đúng thao tác."}</p><div className="hero-actions">{hasAssets&&<a href={`#prompt-${modelNumber}`}>Bắt đầu từ câu lệnh</a>}<a className={hasAssets?"ghost":""} href={`#steps-${modelNumber}`}>Xem thao tác</a></div></div><aside>{hasAssets&&<><div className="flow active"><span>01</span><p><b>Câu lệnh</b>Tải xuống định dạng DOCX</p></div><div className="flow"><span>02</span><p><b>{fileCountText}</b>Xem, sao chép hoặc tải xuống</p></div></>}<div className="flow active"><span>{hasAssets?"03":"01"}</span><p><b>Thao tác đầy đủ</b>Chữ đi cùng đúng ảnh trong video</p></div><div className="flow"><span>{hasAssets?"04":"02"}</span><p><b>Video A–Z</b>Đặt ở cuối trang để xem lại</p></div></aside></section>{hasAssets&&<><section className="content-section prompt-section" id={`prompt-${modelNumber}`}><div className="section-title"><span>PHẦN 01</span><h2>Câu lệnh tạo hệ thống</h2><p>Bạn có thể tải câu lệnh về định dạng DOCX và điều chỉnh theo mong muốn. {fileCountText} ở phần tiếp theo là phiên bản đã được thiết lập và chỉnh sửa sẵn.</p></div><div className="prompt-box"><div className="prompt-actions"><a href={docPath} download>Tải câu lệnh DOCX</a></div><pre>{prompt}</pre></div></section><section className="content-section" id={`codes-${modelNumber}`}><div className="section-title"><span>PHẦN 02</span><h2>{fileCountText} đã thiết lập</h2><p>Mỗi mã nằm trong một khung cuộn cố định. Hãy xem dòng “Lưu mã ở đâu?”, sau đó sao chép hoặc tải tệp.</p></div><div className="code-list">{files.map(f=><CodeCard file={f} key={f.path}/>)}</div></section></>}<section className="content-section" id={`steps-${modelNumber}`}><div className="section-title"><span>{hasAssets?"PHẦN 03":"HƯỚNG DẪN THAO TÁC"}</span><h2>Thao tác thực hiện theo từng bước</h2><p>Mỗi ý hướng dẫn đi cùng ảnh cần thiết được chụp từ video. Ảnh hiển thị toàn chiều rộng; video tương ứng nằm ở cuối từng bước.</p></div><div className="steps">{guide.map((s,i)=><StepCard step={s} index={i} total={guide.length} isAdmin={isAdmin} onChange={x=>changeStep(i,x)} onMove={d=>moveStep(i,d)} onDelete={()=>deleteStep(i)} key={s.id}/>)}</div>{isAdmin&&<button className="add-step" onClick={addStep}>＋ Thêm bước mới</button>}</section><section className="content-section full-video-section" id={`full-video-${modelNumber}`}><div className="full-guide-video"><div className="full-guide-video-head"><span>VIDEO ĐẦY ĐỦ</span><div><h3>Toàn bộ quy trình Mô hình {modelNumber} từ A–Z</h3><p>Xem liền mạch toàn bộ quy trình sau khi đã đọc các bước chi tiết ở phía trên.</p></div></div><SeekableVideo src={fullVideo} label={`Video đầy đủ Mô hình ${modelNumber} từ A đến Z`}/></div></section></>;
}

export default function Home(){
  const pathname=usePathname(),router=useRouter(),isAdmin=pathname==="/admin";
  const defaultGuide2:GuideStep[]=steps2.map(s=>addDefaultPreparation({...s,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages?.map(g=>[...g])||s.details.map(()=>[]),calloutImages:[...(s.calloutImages||[])]}));
  const defaultGuide3:GuideStep[]=steps3.map(s=>addDefaultPreparation({...s,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages?.map(g=>[...g])||s.details.map(()=>[]),calloutImages:[...(s.calloutImages||[])]}));
  const defaultGuide4:GuideStep[]=steps4.map(s=>addDefaultPreparation({...s,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages?.map(g=>[...g])||s.details.map(()=>[]),calloutImages:[...(s.calloutImages||[])]}));
  const defaultGuide5:GuideStep[]=steps5.map(s=>addDefaultPreparation({...s,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages?.map(g=>[...g])||s.details.map(()=>[]),calloutImages:[...(s.calloutImages||[])]}));
  const defaultGuide6:GuideStep[]=steps6.map(s=>addDefaultPreparation({...s,details:[...s.details],callout:s.callout?{...s.callout}:undefined,detailImages:s.detailImages?.map(g=>[...g])||s.details.map(()=>[]),calloutImages:[...(s.calloutImages||[])]}));
  const[view,setView]=useState(()=>viewFromPath(pathname)),[guide,setGuide]=useState<GuideStep[]>(defaultGuide),[savedGuide,setSavedGuide]=useState<GuideStep[]>(defaultGuide),[guide2,setGuide2]=useState<GuideStep[]>(defaultGuide2),[savedGuide2,setSavedGuide2]=useState<GuideStep[]>(defaultGuide2),[guide3,setGuide3]=useState<GuideStep[]>(defaultGuide3),[savedGuide3,setSavedGuide3]=useState<GuideStep[]>(defaultGuide3),[guide4,setGuide4]=useState<GuideStep[]>(defaultGuide4),[savedGuide4,setSavedGuide4]=useState<GuideStep[]>(defaultGuide4),[guide5,setGuide5]=useState<GuideStep[]>(defaultGuide5),[savedGuide5,setSavedGuide5]=useState<GuideStep[]>(defaultGuide5),[guide6,setGuide6]=useState<GuideStep[]>(defaultGuide6),[savedGuide6,setSavedGuide6]=useState<GuideStep[]>(defaultGuide6),[saving,setSaving]=useState(false),[saving2,setSaving2]=useState(false),[saving3,setSaving3]=useState(false),[saving4,setSaving4]=useState(false),[saving5,setSaving5]=useState(false),[saving6,setSaving6]=useState(false),[saveNotice,setSaveNotice]=useState(""),[saveNotice2,setSaveNotice2]=useState(""),[saveNotice3,setSaveNotice3]=useState(""),[saveNotice4,setSaveNotice4]=useState(""),[saveNotice5,setSaveNotice5]=useState(""),[saveNotice6,setSaveNotice6]=useState("");
  useEffect(()=>{if(!isAdmin)setView(viewFromPath(pathname))},[isAdmin,pathname]);
  useEffect(()=>{Promise.all([fetch("/api/guide?model=1").then(r=>r.json()),fetch("/api/guide?model=2").then(r=>r.json()),fetch("/api/guide?model=3").then(r=>r.json()),fetch("/api/guide?model=4").then(r=>r.json()),fetch("/api/guide?model=5").then(r=>r.json()),fetch("/api/guide?model=6").then(r=>r.json())]).then(([g1,g2,g3,g4,g5,g6])=>{if(Array.isArray(g1.guide)){const upgraded=upgradeGuide(g1.guide);setGuide(upgraded);setSavedGuide(upgraded)}if(Array.isArray(g2.guide)){const normalized=g2.guide.map((s:GuideStep,i:number)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0")}));setGuide2(normalized);setSavedGuide2(normalized)}if(Array.isArray(g3.guide)){const normalized=g3.guide.map((s:GuideStep,i:number)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0")}));setGuide3(normalized);setSavedGuide3(normalized)}if(Array.isArray(g4.guide)){const normalized=g4.guide.map((s:GuideStep,i:number)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0")}));setGuide4(normalized);setSavedGuide4(normalized)}if(Array.isArray(g5.guide)){const normalized=g5.guide.map((s:GuideStep,i:number)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0")}));setGuide5(normalized);setSavedGuide5(normalized)}if(Array.isArray(g6.guide)){const normalized=g6.guide.map((s:GuideStep,i:number)=>addDefaultPreparation({...s,n:String(i+1).padStart(2,"0")}));setGuide6(normalized);setSavedGuide6(normalized)}}).catch(()=>{})},[]);
  async function save(model:1|2|3|4|5|6){const current=model===1?guide:model===2?guide2:model===3?guide3:model===4?guide4:model===5?guide5:guide6,setCurrent=model===1?setGuide:model===2?setGuide2:model===3?setGuide3:model===4?setGuide4:model===5?setGuide5:setGuide6,setSaved=model===1?setSavedGuide:model===2?setSavedGuide2:model===3?setSavedGuide3:model===4?setSavedGuide4:model===5?setSavedGuide5:setSavedGuide6,setBusy=model===1?setSaving:model===2?setSaving2:model===3?setSaving3:model===4?setSaving4:model===5?setSaving5:setSaving6,setNotice=model===1?setSaveNotice:model===2?setSaveNotice2:model===3?setSaveNotice3:model===4?setSaveNotice4:model===5?setSaveNotice5:setSaveNotice6;setBusy(true);setNotice("");try{const normalized=current.map((s,i)=>({...s,n:String(i+1).padStart(2,"0")}));const r=await fetch(`/api/guide?model=${model}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({guide:normalized})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Không thể lưu hướng dẫn.");setCurrent(normalized);setSaved(normalized);setNotice("Đã lưu. Khách hàng đang xem phiên bản hoàn chỉnh mới nhất.")}catch(error){setNotice(error instanceof Error?error.message:"Không thể lưu hướng dẫn.")}finally{setBusy(false)}}
  const chooseView=(id:string)=>{if(isAdmin){setView(id);window.scrollTo({top:0,behavior:"smooth"});return}router.push(pathFromView(id))};
  const currentModel=models.find(m=>m.id===view);
  return <main><SiteNav view={view} onSelect={chooseView} isAdmin={isAdmin}/>{view==="home"&&<PortalHome onSelect={chooseView}/>} {view==="model-1"&&<ModelGuidePage modelNumber={1} prompt={promptText} docPath="/files/Cau-lenh-Mo-hinh-1.docx" files={codeFiles} fullVideo="/steps/videos/model1/full-a-z.mp4" guide={guide} savedGuide={savedGuide} isAdmin={isAdmin} saving={saving} saveNotice={saveNotice} onSetGuide={setGuide} onSave={()=>save(1)}/>} {view==="model-2"&&<ModelGuidePage modelNumber={2} prompt={promptText2} docPath="/files/model2/Cau-lenh-Mo-hinh-2.docx" files={codeFiles2} fullVideo="/steps/videos/model2/full-a-z.mp4" guide={guide2} savedGuide={savedGuide2} isAdmin={isAdmin} saving={saving2} saveNotice={saveNotice2} onSetGuide={setGuide2} onSave={()=>save(2)}/>} {view==="model-3"&&<ModelGuidePage modelNumber={3} prompt={promptText3} docPath="/files/model3/Cau-lenh-Mo-hinh-3.docx" files={codeFiles3} fullVideo="/steps/videos/model3/full-a-z.mp4" guide={guide3} savedGuide={savedGuide3} isAdmin={isAdmin} saving={saving3} saveNotice={saveNotice3} onSetGuide={setGuide3} onSave={()=>save(3)}/>} {view==="model-4"&&<ModelGuidePage modelNumber={4} prompt={promptText4} docPath="/files/model4/Cau-lenh-Mo-hinh-4.docx" files={codeFiles4} fullVideo="/steps/videos/model4/full-a-z.mp4" guide={guide4} savedGuide={savedGuide4} isAdmin={isAdmin} saving={saving4} saveNotice={saveNotice4} onSetGuide={setGuide4} onSave={()=>save(4)}/>} {view==="model-5"&&<ModelGuidePage modelNumber={5} prompt={promptText5} docPath="/files/model5/Cau-lenh-Mo-hinh-5.docx" files={codeFiles5} fullVideo="/steps/videos/model5/full-a-z.mp4" guide={guide5} savedGuide={savedGuide5} isAdmin={isAdmin} saving={saving5} saveNotice={saveNotice5} onSetGuide={setGuide5} onSave={()=>save(5)}/>} {view==="model-6"&&<ModelGuidePage modelNumber={6} prompt={promptText6} docPath="/files/model6/Cau-lenh-Mo-hinh-6.docx" files={codeFiles6} fullVideo="/steps/videos/model6/full-a-z.mp4" guide={guide6} savedGuide={savedGuide6} isAdmin={isAdmin} saving={saving6} saveNotice={saveNotice6} onSetGuide={setGuide6} onSave={()=>save(6)}/>} {currentModel&&!["model-1","model-2","model-3","model-4","model-5","model-6"].includes(view)&&<EmptyModel model={currentModel} onHome={()=>chooseView("home")}/>}<footer><div><b>Hướng dẫn 6 mô hình kinh doanh</b><span>Câu lệnh · Mã nguồn · Thao tác · Video</span></div><button onClick={()=>chooseView("home")}>Về mục lục ↑</button></footer></main>;
}
